const html = typeof $input.first().json.data === 'string'
  ? $input.first().json.data
  : JSON.stringify($input.first().json);

const results = [];

// Extract job listings using regex on common HTML patterns
const titleRegex = /<a[^>]+href="(\/job\/[^"]+)"[^>]*>([^<]+)<\/a>/gi;
let match;

while ((match = titleRegex.exec(html)) !== null) {
  const link = match[1].startsWith('http') ? match[1] : 'https://jobs.theguardian.com' + match[1];
  const title = match[2].trim();
  if (title && title.length > 5) {
    results.push({
      json: {
        title: title,
        url: link,
        source: 'guardian_jobs',
        fetched_at: new Date().toISOString()
      }
    });
  }
}

// If no matches found, return a placeholder
if (results.length === 0) {
  results.push({
    json: {
      title: 'Guardian EdTech jobs page scraped (no listings parsed)',
      url: 'https://jobs.theguardian.com/jobs/education-technology/',
      source: 'guardian_jobs',
      fetched_at: new Date().toISOString()
    }
  });
}

return results;

const html = typeof $input.first().json.data === 'string'
