const results = [];

// Extract job listings - jobs.ac.uk typically uses links with /job/ paths
const titleRegex = /<a[^>]+href="([^"]*\/job\/[^"]+)"[^>]*>([^<]+)<\/a>/gi;
let match;

while ((match = titleRegex.exec(html)) !== null) {
  const link = match[1].startsWith('http') ? match[1] : 'https://www.jobs.ac.uk' + match[1];
  const title = match[2].trim();
  if (title && title.length > 5) {
    results.push({
      json: {
        title: title,
        url: link,
        source: 'jobs_ac_uk',
        fetched_at: new Date().toISOString()
      }
    });
  }
}

if (results.length === 0) {
  results.push({
    json: {
      title: 'Jobs.ac.uk EdTech page scraped (no listings parsed)',
      url: 'https://www.jobs.ac.uk/search/?q=education+technology',
      source: 'jobs_ac_uk',
      fetched_at: new Date().toISOString()
    }
  });
}

return results;
